import{_ as i,a0 as p,w as l,s as d,ao as r,I as o,x as a,a1 as e,A as n}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const U=JSON.parse('{"title":"如何在局域网中将Ubuntu文件夹共享给Windows | LCTT x X-CMD","titleTemplate":false,"description":"如何在局域网中将Ubuntu文件夹共享给Windows | LCTT (201505) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何在局域网中将Ubuntu文件夹共享给Windows | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何在局域网中将Ubuntu文件夹共享给Windows | LCTT (201505) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201505/20150304 Share Folders On Local Network Between Ubuntu And Windows","title":"如何在局域网中将Ubuntu文件夹共享给Windows","tag":"201505","desc":""},"relativePath":"201505/20150304 Share Folders On Local Network Between Ubuntu And Windows.md","filePath":"[post].md"}'),u={name:"201505/20150304 Share Folders On Local Network Between Ubuntu And Windows.md"};function m(b,t,h,c,g,f){const s=p("Link");return l(),d("div",null,[t[16]||(t[16]=r(`<h1 id="如何在局域网中将ubuntu文件夹共享给windows" tabindex="-1">如何在局域网中将Ubuntu文件夹共享给Windows <a class="header-anchor" href="#如何在局域网中将ubuntu文件夹共享给windows" aria-label="Permalink to “如何在局域网中将Ubuntu文件夹共享给Windows”">​</a></h1><p><img src="http://itsfoss.itsfoss.netdna-cdn.com/wp-content/uploads/2015/03/Share_Folder_Ubuntu_windows.jpeg" alt=""></p><p>本文全面详细地向你描述了<strong>在Ubuntu中如何实现局域网内的文件夹共享</strong>。</p><p>你的家中是不是有多台电脑？当你需要从一台Ubuntu电脑向另一台电脑传输数据时，是不是必须用到U盘或SD卡？你是否也觉得这个方法很烦人？我想肯定是。本文的目的就是使你在局域网内快速方便地传输文件、文档和其它较大的数据，以节省你的宝贵时间。只需一次设置，然后轻点鼠标，你就可以自由地<strong>在Ubuntu和Windows之间共享文件</strong>，当然这对其它Linux系统同样使用。不要担心，这很容易操作，不会花费太多时间。</p><p>除此之外，尽管本文是在Ubuntu上进行实践，但这个教程在其它Linux系统上同样有用。</p><h4 id="在ubuntu上实现局域网共享文件夹" tabindex="-1">在Ubuntu上实现局域网共享文件夹 <a class="header-anchor" href="#在ubuntu上实现局域网共享文件夹" aria-label="Permalink to “在Ubuntu上实现局域网共享文件夹”">​</a></h4><p>如果你的系统是Ubuntu 14.04、14.10或12.04，有两个方法可以使你通过局域网在搭载Windows或其他Linux的电脑上共享本地文件。</p><ul><li>对局域网中的每个用户提供无密码共享</li><li>仅限特定访问，提供文件夹密码保护</li></ul><p>这篇文章包括两种方法，你可以选择你想用的那种。</p><h3 id="_1-局域网无密码共享文件夹" tabindex="-1">1. 局域网无密码共享文件夹 <a class="header-anchor" href="#_1-局域网无密码共享文件夹" aria-label="Permalink to “1. 局域网无密码共享文件夹”">​</a></h3><h4 id="步骤一" tabindex="-1">步骤一：#### <a class="header-anchor" href="#步骤一" aria-label="Permalink to “步骤一：####”">​</a></h4><p>为了在Ubuntu上实现局域网共享文件夹，右键点击打算共享的文件夹，并选择“Local Network Share（本地网络共享）”：</p><p><img src="http://itsfoss.itsfoss.netdna-cdn.com/wp-content/uploads/2015/02/Share_Folder_Ubuntu.jpeg" alt=""></p><p><strong>可能有用的故障解决方案</strong>：如果在右键菜单中看不到“Local Network Share”的选项，那就新建一个终端，使用下面的命令去安装nautlius-share插件：</p><pre><code>sudo apt-get install nautilus-share
</code></pre><p>然后重启Nautilus。可以选择注销再登录，或者使用这个命令:</p><pre><code>nautilus -q
</code></pre><h4 id="步骤二" tabindex="-1">步骤二：#### <a class="header-anchor" href="#步骤二" aria-label="Permalink to “步骤二：####”">​</a></h4><p>一旦点击“Local Network Share”，就会出现共享文件夹的选项。只需选中“Share this folder（共享该文件夹）”这一项：</p><p><img src="http://itsfoss.itsfoss.netdna-cdn.com/wp-content/uploads/2015/03/Share_Folder_Ubuntu_1.jpeg" alt=""></p><p><strong>可能的故障解决方案</strong>：如果提示共享服务还未安装，就像下图所示，那就点击安装服务，按照提示操作。</p><p><img src="http://itsfoss.itsfoss.netdna-cdn.com/wp-content/uploads/2015/03/Share_Folder_Ubuntu_2.jpeg" alt=""></p><h4 id="步骤三" tabindex="-1">步骤三：#### <a class="header-anchor" href="#步骤三" aria-label="Permalink to “步骤三：####”">​</a></h4><p>当选中“Share this folder”的选项，就会看到按钮“Create Share（创建共享）”变得可以点击了。你也可以“Allow others to create and delete fies in this folder（允许其他用户在共享文件夹中编辑文件）”。选项“Guest access（允许访客访问）”也是如此。</p><p><img src="http://itsfoss.itsfoss.netdna-cdn.com/wp-content/uploads/2015/03/Share_folder_Ubuntu_3.png" alt=""></p><p>你会看到文件夹图标已经显示为共享的。如果要停止共享文件夹，只需取消“Share this floder”这个选项。</p><p>这个方法就是这么简单，使得局域网中的任何人都可以访问共享文件夹中的文件。在正常情况下，你会选择这种方式。因为，家用局域网中的电脑通常都是可信电脑。但情况也不总是这样。如果你只是想特定的用户才能访问怎么办？这个时候就需要Samba服务器了。我们在本文的第二部分讨论这种方法。</p><h3 id="_2-在ubuntu上使用密码保护实现局域网共享文件夹" tabindex="-1">2. 在Ubuntu上使用密码保护实现局域网共享文件夹### <a class="header-anchor" href="#_2-在ubuntu上使用密码保护实现局域网共享文件夹" aria-label="Permalink to “2. 在Ubuntu上使用密码保护实现局域网共享文件夹###”">​</a></h3>`,28)),o("p",null,[t[1]||(t[1]=a("为了达到这个目的，首先需要配置Samba服务器。事实上，在这篇教程的前一部分我们已经用到了Samba，只是我们没有刻意强调。在介绍如何在Ubuntu上搭建Samba服务器实现局域网共享的方法之前，先快速预览一下",-1)),e(s,{href:"http://en.wikipedia.org/wiki/Samba_%28software%29"},{default:n(()=>[...t[0]||(t[0]=[a("Samba",-1)])]),_:1}),t[2]||(t[2]=a("到底是什么。",-1))]),t[17]||(t[17]=r(`<h4 id="samba是什么" tabindex="-1">Samba是什么？ <a class="header-anchor" href="#samba是什么" aria-label="Permalink to “Samba是什么？”">​</a></h4><p>Samba是一个允许用户通过网络共享文件、文档和打印机的软件包，无论是在Linux、Windows，还是Mac上。它适用于所有的主流平台，可以在所有支持系统上流畅运行。下面是维基百科的介绍：</p><blockquote><p>Samba是一款重新实现SMB/CIFS网络协议的自由软件，最初由安德鲁·垂鸠开发。在第三版中，Smaba不仅支持通过不同的Windows客户端访问及分享SMB的文件夹及打印机，还可以集成到Windows Server域，作为主域控制器（PDC）或者域成员。它也可以作为活动目录域的一部分。</p></blockquote><h4 id="在ubuntu上安装samba服务器" tabindex="-1">在Ubuntu上安装Samba服务器 <a class="header-anchor" href="#在ubuntu上安装samba服务器" aria-label="Permalink to “在Ubuntu上安装Samba服务器”">​</a></h4><p>你可以很方便地在Ubuntu电脑上安装Samba。安装前，请先更新系统以便安装任何可用的更新。</p><pre><code>sudo apt-get update &amp;&amp; apt-get upgrade
</code></pre><p>然后按照这条命令安装samba和少量所需的软件包：</p><pre><code>sudo apt-get install samba samba-common system-config-samba python-glade2 gksu
</code></pre><p>一旦安装完成Samba服务器，就可以从图形界面配置Samba来分享文件。</p><h4 id="在ubuntu上配置samba服务器" tabindex="-1">在Ubuntu上配置Samba服务器 <a class="header-anchor" href="#在ubuntu上配置samba服务器" aria-label="Permalink to “在Ubuntu上配置Samba服务器”">​</a></h4><p>从dash中打开Samba配置工具：</p><p><img src="http://itsfoss.itsfoss.netdna-cdn.com/wp-content/uploads/2015/02/Setup-Samba.png" alt=""></p><p>进入到<strong>Preference-&gt;Server Settings</strong>。尽管默认已经设置好，可能就是你需要的。但在某些情况下你可能需要做一些改动。</p><p>在Server Setting中可以看到两个选项卡，‘Basic’和‘Security’。在Basic选项卡下的选项含义如下：</p><ul><li>工作组 - 用户要连接的电脑所在工作组的名字。比如，如果你想连接到一台Windows电脑，你就要输入Windows电脑的工作组名字。在Windows的Samba服务器设置中，已经默认设置好统一的工作组名字。但如果你有不同的工作组名字，就在这个字段中输入自定义的工作组名字。（在Windows 7中获取工作组名字，右击计算机图标，进到属性，就能看到Windows工作组名字。）</li><li>描述 - 其他用户看到的你的电脑名字。不要使用空格或不适用于网络的字符。</li></ul><p><img src="http://itsfoss.itsfoss.netdna-cdn.com/wp-content/uploads/2015/02/samba-server-settings.png" alt=""></p><p>设置samba服务器允许‘Guests’可用是不明智的，所以没必要修改安全设置，保持原样即可。</p><p><img src="http://itsfoss.itsfoss.netdna-cdn.com/wp-content/uploads/2015/02/Samba-Security-Settings-compressed.jpg" alt=""></p><p>这就搞定了！你已经搭建好Samba服务器，距离实现网络共享第一个文件夹的目标不远了！</p><h4 id="为网络文件共享创建一个系统用户" tabindex="-1">为网络文件共享创建一个系统用户 <a class="header-anchor" href="#为网络文件共享创建一个系统用户" aria-label="Permalink to “为网络文件共享创建一个系统用户”">​</a></h4><p>现在我们需要为网络共享文件创建一个系统用户。下面是非常简单的步骤：</p><ul><li>在Systems Settings下点击<strong>User Accounts</strong>。</li><li>点击<strong>unlock</strong>使其可用，以及+（<strong>加号</strong>）图标。</li><li>点击+（加号）图标，创建一个新的系统用户。</li></ul><p><img src="http://itsfoss.itsfoss.netdna-cdn.com/wp-content/uploads/2015/02/create-system-user1.jpg" alt=""></p><p>如上图所示，需要输入‘Full name’。当你输入‘Full name’时，Username会自动填充为Full name。因为创建这个用户是为了共享文件，所以还要指定Account Type为‘<strong>Standard</strong>’。</p><p>完成上述步骤，点击添加，你就创建好一个系统用户。这个用户还没有被激活，所以需要为其设置密码来激活。确保Users accounts界面已经解锁。点击尚不可用的账户，输入一个新密码，然后确认密码，点击Change。</p><p><img src="http://itsfoss.itsfoss.netdna-cdn.com/wp-content/uploads/2015/02/activate-system-user.jpg" alt=""></p><p>耶！到目前为止我们已经安装并配置好Samba，已经创建了一个系统用户以通过这个账户在网络上共享文件，而且也已经激活了新用户。现在来到配置Samba的最后一步，然后就可以共享文件夹了。</p><h4 id="添加samba新用户" tabindex="-1">添加Samba新用户 <a class="header-anchor" href="#添加samba新用户" aria-label="Permalink to “添加Samba新用户”">​</a></h4><p>打开Samba，在Preference先点击Samba Users。填写弹出的对话框，下面是其中几个字段的说明：</p><p><strong>Unix Username</strong> - 在这种情况下，我选择刚才创建的用户。</p><p><strong>Windows Username</strong> - 输入你要访问的Windows电脑的用户名。</p><p><strong>Samba Password</strong> - 输入你要访问的Windows电脑的密码。</p><p><img src="http://itsfoss.itsfoss.netdna-cdn.com/wp-content/uploads/2015/02/samba-user-setting.jpg" alt=""></p><p>完成后点击OK。现在做个深呼吸。你已经在Samba的帮助下成功创建一个网络。然后重启网络或Samba服务，准备好和其它电脑共享文件。</p><pre><code>sudo restart smbd &amp;&amp; sudo restart nmbd
</code></pre><h4 id="通过网络共享文件夹或文件" tabindex="-1">通过网络共享文件夹或文件 <a class="header-anchor" href="#通过网络共享文件夹或文件" aria-label="Permalink to “通过网络共享文件夹或文件”">​</a></h4><p>在图形用户界面下通过Samba共享文件是很简单的。点击加号图标，会看到如图所示的对话框：</p><p><img src="http://itsfoss.itsfoss.netdna-cdn.com/wp-content/uploads/2015/02/share-files-and-folders.jpg" alt=""></p><p>填写完这些字段。在‘Directory’中，浏览要共享的文件夹。你会看到的字段的含义如下：</p><ul><li><strong>Share name</strong> 是其它人会看到的文件夹名字。</li><li><strong>Description</strong> 是要共享内容的简单描述。</li><li><strong>Writeable</strong> 默认情况下共享的文件夹是‘read only’。如果允许网络上的其他用户修改它们，设置为writable。</li><li><strong>Visiable</strong> 当你点击Visiable时，就像它的名字一样，共享文件夹就对网络上的其他人可见。</li></ul><p>现在你可以设置共享文件夹的权限。点击‘Access’选项，选择想要共享文件夹的用户。当你选择对所有人允许访问后，这个文件夹就对网络上的所有人可见。</p><p><img src="http://itsfoss.itsfoss.netdna-cdn.com/wp-content/uploads/2015/02/Screenshot-from-2015-02-28-202031.png" alt=""></p><p>最后点击OK，完成共享。现在这个文件夹就与你想要共享的用户实现共享。你已经完成了网络共享文件。还有其它要做的吗？对！还不知道如何从网络上移除文件夹？</p><h4 id="移除共享文件夹" tabindex="-1">移除共享文件夹 <a class="header-anchor" href="#移除共享文件夹" aria-label="Permalink to “移除共享文件夹”">​</a></h4><p>在网络共享一段时间后，我们也需要移除其中的一些文件夹。操作很简答，下面就是我们要做的。</p><p><img src="http://itsfoss.itsfoss.netdna-cdn.com/wp-content/uploads/2015/02/remove-shared-folder-from-network.jpg" alt=""></p><p>全部搞定！我们也可以使用终端进行网络文件共享，但这样没有本文介绍的方法这么容易。如果你确实想知道命令行操作，我会再写一篇关于在Linux上使用命令行实现网络文件共享的文章。</p><p>所以，你是怎么找到这篇教程的呢？我希望看了这篇教程你可以<strong>很容易地在Ubuntu和Windows之间共享文件</strong>。如果你有任何问题或建议，请在评论里说出来。</p><hr>`,49)),o("p",null,[t[4]||(t[4]=a("via: ",-1)),e(s,{href:"http://itsfoss.com/share-folders-local-network-ubuntu-windows/"},{default:n(()=>[...t[3]||(t[3]=[a("http://itsfoss.com/share-folders-local-network-ubuntu-windows/",-1)])]),_:1})]),o("p",null,[t[8]||(t[8]=a("作者：",-1)),e(s,{href:"http://itsfoss.com/author/sohail/"},{default:n(()=>[...t[5]||(t[5]=[a("Mohd Sohail",-1)])]),_:1}),t[9]||(t[9]=a(" 译者：",-1)),e(s,{href:"https://github.com/KayGuoWhu"},{default:n(()=>[...t[6]||(t[6]=[a("KayGuoWhu",-1)])]),_:1}),t[10]||(t[10]=a(" 校对：",-1)),e(s,{href:"https://github.com/wxy"},{default:n(()=>[...t[7]||(t[7]=[a("wxy",-1)])]),_:1})]),o("p",null,[t[13]||(t[13]=a("本文由 ",-1)),e(s,{href:"https://github.com/LCTT/TranslateProject"},{default:n(()=>[...t[11]||(t[11]=[a("LCTT",-1)])]),_:1}),t[14]||(t[14]=a(" 原创翻译，",-1)),e(s,{href:"http://linux.cn/"},{default:n(()=>[...t[12]||(t[12]=[a("Linux中国",-1)])]),_:1}),t[15]||(t[15]=a(" 荣誉推出",-1))])])}const _=i(u,[["render",m]]);export{U as __pageData,_ as default};
